# 35_fig_expected_movements.R — FIGURE 2.11 (REVISED 29 Jul). Expected and unexpected movements in
# public opinion.
#
# THE QUESTION. When the public says it is worried about something, is that movement explained by
# what was actually happening? The explained part is the EXPECTED movement — the democratic signal
# doing its job. The unexplained part is the UNEXPECTED movement, and the chapter's interest is
# whether that part has grown, and whether it persists or churns.
#
# DESIGN DECISIONS (dated, so the reasoning survives even if this file is edited again):
#   28 Jul — NOT public spending (government output, opinion partly drives it, arrow runs both ways).
#   28 Jul — match each ITEM to its OWN actual, not the CAP topic composite (scripts 31/32 superseded).
#   28 Jul — raw percent, not agenda share (compositional, manufactures mean reversion).
#   29 Jul — extended to 13 items (36_expected_movements_all_items.R); of those, only Unemployment,
#     Inflation, Trade unions, Petrol and Education are BOTH correctly signed AND clear R^2>=0.40 —
#     see all_items_tracking_stats.csv. Poverty and Drugs are wrong-signed and stay out of the
#     composite regardless of R^2: a backwards relationship is not evidence of tracking.
#   29 Jul — uniform COVID rule: every fit excludes 2020-21, but residuals/expected values are still
#     computed for those years by predicting from the non-COVID model.
#   29 Jul evening — RESHAPED PER PJ'S STEER, four panels:
#     A: ALL 13 items' unexpected movement overlaid ("lots of lines" — breadth/external validity is
#        the point of this panel, not any one item's precision; see house-style greyscale grouping
#        below for how the composite's 5 constituents are visually distinguished from the other 8).
#     B: the COMPOSITE unexpected indicator (unchanged from the earlier draft's panel C).
#     C: a PCA of the composite's item residuals + agenda fragmentation (ENI) — PJ: "try it", "feed
#        into the big PCA at the end". Result is WEAK (PC1 only 38.5% of variance, misses the
#        1979-86 episode entirely) — flagged on the panel itself, not hidden. See FIG211_NOTES.md s14.
#     D: a Chow F-sweep on the composite — PJ: "a chow, to be consistent" with how every other break
#        claim in the book is shown (the standardised chow_panel_figure() F-curve, chow_test.R).
#     Persistence (the earlier draft's panel D, rolling AR(1)) MOVED to the robustness appendix — see
#     robustness_checks/RC02_ch2_expected_movements_persistence/. A genuine finding, just not one of
#     the four things this main-text figure needs to carry.
#
# BREAK TEST ON |unexpected|: run, reported in the console/notes, NOT put on the figure — the F-sweep
# is significant but bimodal (two candidate dates effectively tied), so any single date would be
# spurious precision. Same call as the KL panel on Fig 2.10. See FIG211_NOTES.md for the numbers.
if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr, tidyr, ggplot2, ggrepel, patchwork, purrr, tibble, zoo)
.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(dirname(sub("^--file=", "", m))) else getwd()
})
setwd(.ROOT)
source("../chow_standardized/chow_test.R")
START <- 1979
LABELPAD <- 7
COVID_YEARS <- c(2020, 2021)

house <- theme_minimal(base_size=10) +
  theme(panel.grid.minor=element_blank(), panel.grid.major.x=element_blank(), legend.position="none",
        plot.subtitle=element_text(face="italic", colour="grey30", size=9),
        axis.title=element_text(size=9, colour="grey20"), plot.tag=element_text(face="bold", size=11))

# ---- data ---------------------------------------------------------------------------------------
mon <- read_csv("ipsos_issues_index_monthly_1974_2026_mapped.csv", show_col_types=FALSE)
nm  <- mon |> group_by(year) |> summarise(nmo=n_distinct(month), .groups="drop")
END <- max(nm$year[nm$nmo >= 6])
# +LABELPAD on every panel (not just A) so all four stay aligned on the shared x-axis — same
# convention as Fig 2.10 (29_fig_agenda_no_pca.R), which extends xlim project-wide when any panel
# carries ggrepel end-labels, rather than giving the labelled panel its own axis range.
xaxis <- list(scale_x_continuous(breaks=seq(1980, END, 5)), coord_cartesian(xlim=c(START, END+LABELPAD)))

# ---- break test on the SIZE of the unexpected movement (reported, not plotted — see header) ------
allitems <- read_csv("all_items_expected.csv", show_col_types=FALSE)
brk <- allitems |> group_split(item) |> map(function(d){
  b <- chow_sweep(d$year, abs(d$unexpected))
  b$item <- d$item[1]; b })
names(brk) <- map_chr(brk, "item")
cat("\n=== BREAK TEST on |unexpected| (house sup-F, 15% trim, 10,000 perms, seed 42) — NOT on figure ===\n")
for (b in brk) cat(sprintf("%-24s peak %d  F=%.2f  crit5%%=%.2f  perm p=%.4f  slope %.3f -> %.3f pp/yr\n",
  b$item, b$peak_year, b$peak_F, b$crit_5pct, b$perm_p, b$slope_before, b$slope_after))

# ---- panel A: all 13 items' unexpected movement overlaid ------------------------------------------
