# convention 38_composite_unexpected_index.R already uses for the composite), so all 13 lines are
# now in genuinely comparable z-score units, consistent with panels B and C.
COMPOSITE_ITEMS <- c("Unemployment","Inflation","Trade unions / strikes","Petrol / fuel","Education")
COMPOSITE_LABELS <- c(Unemployment="Unemployment", Inflation="Inflation",
                       `Trade unions / strikes`="Trade unions", `Petrol / fuel`="Petrol", Education="Education")
COMPOSITE_LTYS <- c(Unemployment="solid", Inflation="longdash", `Trade unions / strikes`="dashed",
                    `Petrol / fuel`="dotdash", Education="twodash")
WRONG_SIGNED <- c("Poverty","Drugs")
item_sd <- read_csv("all_items_tracking_stats.csv", show_col_types=FALSE) |>
  filter(status=="ok") |> select(item, resid_sd)
panelA_dat <- allitems |> filter(year>=START, year<=END) |>
  left_join(item_sd, by="item") |> mutate(unexpected_z = unexpected / resid_sd) |>
  mutate(grp = case_when(item %in% COMPOSITE_ITEMS ~ "composite",
                          item %in% WRONG_SIGNED ~ "wrong_signed",
                          TRUE ~ "other"))
labA <- panelA_dat |> filter(grp=="composite") |> group_by(item) |> filter(year==max(year)) |>
  ungroup() |> mutate(lab=COMPOSITE_LABELS[item])
pA <- ggplot(panelA_dat, aes(year, unexpected_z, group=item)) +
  geom_hline(yintercept=0, colour="grey70", linewidth=0.4) +
  geom_line(data=subset(panelA_dat, grp=="other"), colour="grey65", linewidth=0.45, alpha=0.8) +
  geom_line(data=subset(panelA_dat, grp=="wrong_signed"), colour="grey65", linewidth=0.45,
            linetype="22", alpha=0.8) +
  geom_line(data=subset(panelA_dat, grp=="composite"), aes(linetype=item), colour="grey15", linewidth=0.7) +
  scale_linetype_manual(values=COMPOSITE_LTYS, guide="none") +
  geom_text_repel(data=labA, aes(x=year, y=unexpected_z, label=lab), colour="grey15", hjust=0, size=2.7,
    direction="y", nudge_x=2, segment.size=0.2, segment.colour="grey80", min.segment.length=0,
    xlim=c(END+0.8, END+LABELPAD)) +
  xaxis + labs(tag="A", x=NULL, y="Unexpected movement (z, own SD)",
    subtitle="Opinion minus real-world conditions") +
  house
