# ---- panel C: PCA of expectations + fragmentation (TRIED PER PJ'S STEER, RESULT IS WEAK — see
# FIG211_NOTES.md s14/s17 for the full writeup). EXTENDED 29 Jul night per PJ ("still a good idea to
# get a full range from 1979... may need some patching") — the original build (4 residuals + ENI,
# 1987-2023) cut out the 1979-86 episode entirely. Chased this down:
#   - PETROL DROPPED from this panel's variable set. Its real (RPI-deflated) index genuinely cannot
#     start before 1987: ONS rebased the whole RPI to Jan-1987=100 and the pre-1987 "petrol and oil"
#     sub-index isn't in their public ad-hoc historical archive (checked: the ONS 1956-86 ad-hoc
#     covers electricity/gas/fuel-and-light only, NOT petrol). The Bank of England's "Millennium of
#     Macroeconomic Data" does contain a UK oil-price series (FRED mirrors it as OLPRUKA) but it could
#     not be extracted through any available tool (FRED blocks direct fetch; the BoE/datahub/GitHub
#     CSV mirrors are too large for the fetch tool to scan in full — tried all three, each failed).
#     Rather than fabricate 8 years of petrol data, it is dropped from this panel; Une/Inf/TU/ENI
#     already carry the panel and are the most complete series available anyway.
#   - 1979 itself is NOT reachable even after dropping Petrol: Inflation and Trade unions both use a
#     one-year-LAG spec (worry ~ actual + actual(t-1), the composite's own best-fitting spec), which
#     structurally consumes their first observation — their residual series starts in 1980 by
#     construction, not because of a data gap. Extending to 1979 would mean extrapolating past the
#     model's own valid domain, which is a worse kind of patching than any applied here, so it isn't
#     done. 1980 is the genuine earliest year.
#   - 1981 (the one universal gap in the whole Ipsos series, already the convention throughout this
#     book: line plots join 1980 straight to 1982) is likewise NOT interpolated — dropped as a single
#     row, same as everywhere else, no fabricated value.
#   - Trade unions' 2020-22 gap (BBFW data collection was paused during COVID, a documented, dated
#     cause, not an unknown) IS linearly interpolated — the one genuine "patch" applied, disclosed in
#     the figure's footnote/text, not on the panel itself (PJ, 31 Jul: no commentary on panels).
# Net effect: coverage goes from 34 obs (1987-2023) to 43 obs (1980-2023) — as close to "the whole
# series" as is honestly achievable without either fabricating data or extrapolating past a model's
# valid range. PC1 is barely changed (39.3% of variance vs 38.5% before, re-verified 31 Jul after the
# calendar-lag bug fix — corrected from an earlier, stale "40.4%" quoted in FIG211_NOTES.md §16/17/18,
# see §34) — extending the range doesn't fix the underlying weakness, it just stops the panel from
# silently hiding the 1980s.
res_wide <- read_csv("composite_item_residuals.csv", show_col_types=FALSE) |>
  select(item, year, z) |> pivot_wider(names_from=item, values_from=z)
agenda <- read_csv("agenda_indices_annual.csv", show_col_types=FALSE) |> select(year, eni)
pca_dat <- res_wide |>
  select(year, Unemployment, Inflation, `Trade unions / strikes`) |>
  full_join(agenda, by="year") |> arrange(year) |> filter(year>=1980, year<=2023)
pca_dat$`Trade unions / strikes` <- zoo::na.approx(pca_dat$`Trade unions / strikes`,
                                                    x=pca_dat$year, na.rm=FALSE)
pca_cc <- pca_dat[complete.cases(pca_dat), ]
pc <- prcomp(pca_cc |> select(-year), scale.=TRUE)
pc1_var <- round(summary(pc)$importance[2,1]*100, 1)
pca_cc$PC1 <- pc$x[,1]
cat(sprintf("\n=== PANEL C PCA (expectations + fragmentation, Petrol dropped, TU interpolated 2020-22): PC1 = %.1f%% of variance, n=%d, %d-%d ===\n",
            pc1_var, nrow(pca_cc), min(pca_cc$year), max(pca_cc$year)))
print(round(pc$rotation[,1:2], 3))

pC <- ggplot(pca_cc, aes(year, PC1)) +
  geom_hline(yintercept=0, colour="grey70", linewidth=0.4) +
  geom_line(colour="black", linewidth=0.7) + geom_point(colour="black", size=1.1) +
  xaxis + labs(tag="C", x=NULL, y="PC1 (attention residuals + fragmentation)",
    subtitle="PCA: Unemployment, Inflation, Trade unions + fragmentation index") +
  house
# Subtitle names what's combined (descriptive) but not the % variance explained — that's a result,
