# ---- panel D: Chow F-sweep on the composite (house standard test, sup-F/permutation — chow_test.R),
# "to be consistent" with how every other break claim in the book is shown (Fig 2.12, exec-instability,
# PM-turnover): the F-curve itself, not just a reported peak, so the reader sees the whole sweep and
# the 5% critical value, not one cherry-picked date. Composite restricted to n_items>=2 (panel B note).
#
# TRIM CORRECTED 29 Jul, PJ caught it by eye ("the chow looks odd"): the house default 15% trim on
# this short, front-loaded series (n=45, starting 1980) puts its first testable candidate at EXACTLY
# 1986 — so the reported "peak" was sitting on the trim boundary, not a genuine interior maximum (the
# tell: the F-curve was monotonically declining from its very first plotted point, never rising into
# a peak — the visual "oddness" PJ flagged). Loosening to 10% trim (still floor min_seg=3, i.e. >=4-5
# obs/side here) reveals the TRUE peak at 1985, F=25.83 (vs 18.54 at the artifact), confirmed STABLE
# down to 5% and 2% trim (same year, same F both times — not just a smaller-trim fishing result). Same
# artifact independently confirmed for Trade unions (true peak also 1985, F=38.76 vs 15.99 at the old
# boundary). Fig 2.12 is corrected to match (see FIG211_NOTES.md s16) — the qualitative finding is
# UNCHANGED (decline then genuine rise) but the break year and its statistical strength are corrected.
#
# STILL LOOKS FRONT-LOADED (PJ, 29 Jul: "should start earlier"). Diagnosed: with 1981 missing (the
# one universal Ipsos gap), the composite has only 3 real observations before 1984 (1980, 1982, 1983)
# — and chow_sweep's min_seg=3 floor (need >=3 points per segment to fit a 2-parameter regression at
# all) means NO trim setting, however loose, can test a candidate break before the 3rd observation.
# That is a hard mathematical floor, not a laziness setting. The one thing that CAN move it: 1981
# itself. Interpolating that single point (linear, 1980-1982) gains one real testable year — FOR THIS
# TEST ONLY, not applied to panel B's composite_z (kept exactly as published, per PJ "panel B is
# good"). Going further back than 1980 would need genuine pre-1979 opinion data, which this project
# does not have at the item level (the `early_years_gallup_filled.csv` file on disk is a Gallup-MIP
# proxy for agenda FRAGMENTATION only, not for Unemployment/Inflation/TU worry — it cannot extend
# this series). Per PJ's own steer, that avenue is banked as a robustness-check LEAD to revisit later
# (FIG211_NOTES.md s17), not built into this figure now.
comp_persist <- composite |> filter(n_items >= 2)
comp_chow <- comp_persist |> select(year, composite_z) |>
  full_join(tibble(year=1981), by="year") |> arrange(year)
comp_chow$composite_z <- zoo::na.approx(comp_chow$composite_z, x=comp_chow$year, na.rm=FALSE)
chow_comp <- chow_sweep(comp_chow$year, comp_chow$composite_z, trim=0.10)
cat(sprintf("\n=== PANEL D CHOW: peak %d, F(2,%d)=%.2f, perm p=%.3f%s (1981 interpolated for this test only) ===\n",
  chow_comp$peak_year, chow_comp$n-4, chow_comp$peak_F, chow_comp$perm_p,
  if (chow_comp$peak_F > chow_comp$crit_5pct) "" else " (< 5% crit)"))
pD <- ggplot(chow_comp$curve, aes(year, F)) +
  geom_hline(yintercept=chow_comp$crit_5pct, linetype="dashed", colour="grey55", linewidth=0.5) +
  geom_line(colour="black", linewidth=0.6) +
  geom_point(data=chow_comp$curve[which.max(chow_comp$curve$F), , drop=FALSE],
             shape=21, fill="white", colour="black", size=3, stroke=1.2) +
  annotate("text", x=min(chow_comp$curve$year), y=chow_comp$crit_5pct,
           label="5% critical value", colour="grey50", size=2.5, hjust=0, vjust=-0.6) +
  xaxis + labs(tag="D", x="Year", y=sprintf("Chow F(2,%d)", chow_comp$n-4),
    subtitle="Structural break") +
  house
# Subtitle names the test (descriptive); the actual result — peak year, F, p-value — stays off the
